            float v = c[bsp::kPilotCmdYaw];
            if (!ga_band_search_0099b940(u, 0, v)) {
                v = u.plane_bank_angle_c68 <= 0.0f ? -1.1f : 1.1f;
            }
            finish(c[bsp::kPilotCmdYaw], v);
