        GameGunneryHost* const gun = gunnery.get();
        if (gun == nullptr || m >= slots.size() || gun->unit_dead(m)) return;
        if (sq == nullptr) {
            record("Plane::exit_zone_party_007ca790", 0x007ca790u);   // no 007F31A0
            return;
        }
