        v.handle = static_cast<std::uint32_t>(list_[index] + 1);
        v.side_54 = u.row.party;
        v.position_fc = Vec3{u.motion.position[0], u.motion.position[1], u.motion.position[2]};
        v.inferior_range_7c8 = u.inferior_range_7c8;
