            GameUnitSlot& u = *h.slots[m];
            if (u.command_target_plus_one == fa.override_target) u.command_target_plus_one = 0;
            u.moveto_task_installed = false;
            u.moveto_state = GameUnitSlot::MoveToTaskState::kNone;
