                        if (!arc) {
                            for (int i = 0; i < 3; ++i)
                                out[i] = static_cast<float>(p[i] + v[i] * time);
                            return false;
                        }
                        const double r = s / rate;
                        const double c[3] = {p[0] + r * d[0], p[1] + r * d[1], p[2] + r * d[2]};
                        // 004F9B30: axis = d x n.
                        const double ax[3] = {d[1] * n[2] - d[2] * n[1], d[2] * n[0] - d[0] * n[2],
                                              d[0] * n[1] - d[1] * n[0]};
