                            const float xb = static_cast<float>(static_cast<double>(f) * 150.0 + m);
                            const float b = clamped_interpolate_00419010(150.0f, 0.05f, 50.0f, T, xb);
                            const float m2 = static_cast<float>(-static_cast<double>(T) * 2.0);
