                            const float sr = static_cast<float>(static_cast<double>(v) / stall_range);
                            const float a = clamped_interpolate_00419010(1.4f, 0.05f, 1.8f, T, sr);
                            const float b = clamped_interpolate_00419010(80.0f, 0.05f, 30.0f, T, m);
                            P = a > b ? a : b;
